        [['question' => 'In PostgreSQL, is VARCHAR(100) faster on disk or in indexes than TEXT?', 'answer' => 'No—both use the identical internal varlena structure; VARCHAR(n) actually adds an extra length-check step', 'options' => ['No—both use the identical internal varlena structure; VARCHAR(n) actually adds an extra length-check step', 'Yes, VARCHAR(100) is 10x faster', 'TEXT cannot be indexed by B-Tree', 'TEXT is stored outside WAL']], ['question' => 'How many bytes does PostgreSQL\'s native UUID column type occupy compared to VARCHAR(36)?', 'answer' => '16 bytes (vs 37+ bytes for VARCHAR(36))', 'options' => ['16 bytes (vs 37+ bytes for VARCHAR(36))', '64 bytes', '4 bytes', '36 bytes']], ['question' => 'Why should you always choose TIMESTAMPTZ over TIMESTAMP WITHOUT TIME ZONE in Postgres?', 'answer' => 'Both use 8 bytes, and TIMESTAMPTZ normalizes to UTC safely instead of silently dropping timezone offsets', 'options' => ['Both use 8 bytes, and TIMESTAMPTZ normalizes to UTC safely instead of silently dropping timezone offsets', 'TIMESTAMPTZ uses only 2 bytes', 'TIMESTAMP cannot be sorted', 'TIMESTAMPTZ disables leap years']]],
