    pg_ch('1. Architecture, Types & DDL Mastery', 'DDL Constraints, Identity Columns, UPSERT (ON CONFLICT) & RETURNING', 'postgres generated always as identity, insert on conflict do update, postgres returning clause, check exclude constraints',
        'PostgreSQL eliminates round-trip `SELECT LAST_INSERT_ID()` calls via **`RETURNING *`** on `INSERT`/`UPDATE`/`DELETE` and handles atomic idempotent writes via **`INSERT ... ON CONFLICT DO UPDATE`** (`EXCLUDED`).',
        ['**Why `GENERATED ALWAYS AS IDENTITY` Beats `SERIAL`**: Legacy `SERIAL` lets manual `INSERT INTO t(id) VALUES (5)` advance rows **without** advancing the underlying sequence—causing a shocking duplicate-key crash days later when the sequence catches up to `5`! `GENERATED ALWAYS AS IDENTITY` prevents accidental manual overrides.', '**`RETURNING id, created_at`**: Works on `INSERT`, `UPDATE`, and `DELETE`—returning modified rows in a **single** network round-trip!', '**Transactional DDL**: Unlike MySQL (where `ALTER TABLE` implicitly commits transactions!), **PostgreSQL DDL is 100% transactional**—you can wrap `BEGIN; ALTER TABLE ...; CREATE INDEX ...; ROLLBACK;` safely!'],
        [['`GENERATED ALWAYS AS IDENTITY`', 'SQL-standard auto-increment primary key', 'Prevents sequence desynchronization bugs common with `SERIAL`.'], ['`ON CONFLICT (email) DO UPDATE SET ...`', 'Atomic upsert referencing incoming values via `EXCLUDED.col`', 'Note: even `DO NOTHING` conflicts increment the sequence gap—normal behavior!'], ['`Transactional DDL`', '`CREATE`/`ALTER`/`DROP` can roll back inside `BEGIN ... ROLLBACK`!', 'Exception: `CREATE INDEX CONCURRENTLY` cannot run inside a transaction block.']],
        "CREATE TABLE feature_flags (\n  id SERIAL PRIMARY KEY,\n  flag_key TEXT UNIQUE NOT NULL,\n  enabled INTEGER NOT NULL DEFAULT 0\n);\nINSERT INTO feature_flags (flag_key, enabled) VALUES ('ai_tutor_v2', 1);\nSELECT * FROM feature_flags;",
        ['**Huge PostgreSQL Superpower**: Because DDL is transactional in Postgres, if migration step #4 fails halfway through a multi-statement migration, Postgres rolls back steps #1–#3 cleanly instead of leaving a half-migrated broken schema!'],
        [['question' => 'What nasty production bug does GENERATED ALWAYS AS IDENTITY prevent compared to legacy SERIAL?', 'answer' => 'Manual ID inserts leaving the sequence counter behind and causing future duplicate-key crashes', 'options' => ['Manual ID inserts leaving the sequence counter behind and causing future duplicate-key crashes', 'Integer overflow at 1,000', 'Null foreign keys', 'UTF-8 encoding errors']], ['question' => 'Inside INSERT ... ON CONFLICT (sku) DO UPDATE, what special table alias holds the proposed incoming row values?', 'answer' => 'EXCLUDED (e.g. EXCLUDED.price)', 'options' => ['EXCLUDED (e.g. EXCLUDED.price)', 'VALUES()', 'NEW_ROW', 'INCOMING']], ['question' => 'Can ALTER TABLE and DROP TABLE statements be rolled back inside a BEGIN ... ROLLBACK transaction in PostgreSQL?', 'answer' => 'Yes—PostgreSQL supports transactional DDL!', 'options' => ['Yes—PostgreSQL supports transactional DDL!', 'No, DDL always auto-commits in Postgres', 'Only on SQLite', 'Only in read-only replicas']]],
