    pg_ch('2. Advanced SQL, CTEs, Window Functions & JSONB', 'Filtering, ILIKE, COALESCE, Joins, LATERAL Joins & FILTER Aggregates', 'postgres lateral join, filter where aggregate, ilike vs like, nullif coalesce postgres',
        'Beyond standard SQL joins, PostgreSQL unlocks **`LATERAL` joins** (allowing a right-hand subquery to reference columns from the left-hand table—like a correlated `forEach` in SQL!) and clean **`COUNT(*) FILTER (WHERE ...)`** conditional aggregations.',
        ['**`COUNT(*) FILTER (WHERE status = \'paid\')`**: Replaces verbose `SUM(CASE WHEN status = \'paid\' THEN 1 ELSE 0 END)` with crystal-clear readable SQL!', '**`LEFT JOIN LATERAL (...) ON true`**: The cleanest, fastest way in Postgres to fetch the **"Top 3 most recent orders for each customer"** using an index seek per customer!', '**`DISTINCT ON (user_id)`**: Postgres-exclusive clause returning the single first row per group according to `ORDER BY user_id, created_at DESC`.'],
        [['`ILIKE \'%nectra%\'`', 'Case-insensitive pattern match', 'Pair with `pg_trgm` `GIN` trigram index to make `%substring%` `ILIKE` blazing fast!'], ['`COUNT(*) FILTER (WHERE ...)`', 'Conditional aggregate filter', 'Works with `COUNT`, `SUM`, `AVG`, `ARRAY_AGG`!'], ['`CROSS/LEFT JOIN LATERAL`', 'Subquery referencing outer table columns', 'Solves "Top-N per category" cleanly with index scans.']],
        "SELECT country,\n       COUNT(*) AS total_customers,\n       ROUND(AVG(discount_rate) * 100, 1) AS avg_discount_pct\nFROM customers\nGROUP BY country\nORDER BY total_customers DESC;",
        ['Need fast `%search%` wildcard matching on 10 million rows? Standard B-Tree indexes cannot accelerate leading wildcards (`%foo`), **but** PostgreSQL\'s `CREATE EXTENSION pg_trgm; CREATE INDEX ON products USING gin (name gin_trgm_ops);` accelerates both `LIKE \'%foo%\'` AND `ILIKE \'%foo%\'` to milliseconds!'],
        [['question' => 'Which PostgreSQL extension + index type accelerates leading-wildcard ILIKE "%term%" searches to milliseconds?', 'answer' => 'pg_trgm with a GIN (or GiST) trigram index', 'options' => ['pg_trgm with a GIN (or GiST) trigram index', 'Standard B-Tree index', 'BRIN index', 'UUID extension']], ['question' => 'What makes a LATERAL join unique compared to a standard derived-table subquery join?', 'answer' => 'The LATERAL subquery can reference columns from preceding tables in the FROM clause', 'options' => ['The LATERAL subquery can reference columns from preceding tables in the FROM clause', 'It joins across two separate servers automatically', 'It skips foreign keys', 'It deletes unmatched rows']], ['question' => 'Which SQL-standard clause supported by Postgres cleanly replaces SUM(CASE WHEN cond THEN 1 ELSE 0 END)?', 'answer' => 'COUNT(*) FILTER (WHERE cond)', 'options' => ['COUNT(*) FILTER (WHERE cond)', 'COUNT_IF(cond)', 'SUM_WHERE(cond)', 'HAVING COUNT(cond)']]],
