    pg_ch('3. Indexing, Query Plans, Security & AI Scale', 'Postgres Index Types (B-Tree, GIN, GiST, BRIN, Partial, Covering) & EXPLAIN ANALYZE', 'postgres index types, brin gin gist btree, partial index postgres, create index concurrently, explain analyze buffers',
        'PostgreSQL offers **6 specialized index access methods** plus **Partial Indexes**, **Expression Indexes**, **Covering (`INCLUDE`) Indexes**, and zero-downtime **`CREATE INDEX CONCURRENTLY`**.',
        ['**Never Lock Production Writes (`CONCURRENTLY`)**: Standard `CREATE INDEX` takes a `SHARE` lock blocking ALL `INSERT`/`UPDATE`/`DELETE` on the table! Always run **`CREATE INDEX CONCURRENTLY`** on live production tables!', '**Partial Indexes (`WHERE status = \'pending\'`)**: If 99.5% of 50M orders are `delivered` and workers only poll `pending` orders, indexing `WHERE status = \'pending\'` makes the index **200x smaller**!', '**`BRIN` (Block Range Index)**: Stores min/max summaries per 128-page disk range—turning a `40 GB` B-Tree on a billion-row append-only `created_at` log table into a **`2 MB` BRIN index**!', '**Always Include `BUFFERS` in `EXPLAIN`**: Run `EXPLAIN (ANALYZE, BUFFERS)` (`shared hit` = RAM cache, `shared read` = slow disk I/O)! Note: `EXPLAIN ANALYZE` **actually executes** the query—wrap `EXPLAIN ANALYZE DELETE/UPDATE` inside `BEGIN; ... ROLLBACK;`!'],
        [['`B-Tree` (Default)', '`=`, `<`, `<=`, `>`, `>=`, `BETWEEN`, `IS NULL`, `ORDER BY`', 'Add `INCLUDE (email, name)` to enable **Index-Only Scans**!'], ['`Partial Index` (`WHERE deleted_at IS NULL`)', 'Indexes only active subset of rows', 'Dramatically shrinks index RAM & speeds up writes on non-matching rows!'], ['`Expression Index` (`ON users (LOWER(email))`)', 'Accelerates `WHERE LOWER(email) = \'...\'`', 'Standard `(email)` index is bypassed if wrapped in `LOWER(email)`!'], ['`CREATE INDEX CONCURRENTLY`', 'Builds index without blocking table writes', 'If interrupted, check `\d` for `INVALID` index and `DROP INDEX CONCURRENTLY` before retrying!']],
        "EXPLAIN SELECT customer_name, country FROM customers WHERE country = 'Germany';",
        ['**Danger Note on `EXPLAIN ANALYZE`**: Unlike plain `EXPLAIN`, `EXPLAIN ANALYZE DELETE FROM orders;` **physically deletes your rows** to measure actual runtime! Always wrap mutating `EXPLAIN ANALYZE` statements inside `BEGIN; EXPLAIN ANALYZE ...; ROLLBACK;`!'],
        [['question' => 'Why MUST you run CREATE INDEX CONCURRENTLY instead of CREATE INDEX on a busy production PostgreSQL table?', 'answer' => 'Standard CREATE INDEX blocks all INSERT, UPDATE, and DELETE writes until the index build finishes', 'options' => ['Standard CREATE INDEX blocks all INSERT, UPDATE, and DELETE writes until the index build finishes', 'CREATE INDEX drops existing rows', 'CONCURRENTLY skips WAL completely', 'Standard indexes expire after reboot']], ['question' => 'What happens if you run EXPLAIN ANALYZE DELETE FROM users; outside a rolled-back transaction?', 'answer' => 'PostgreSQL actually executes the DELETE and removes the rows to measure real execution timing!', 'options' => ['PostgreSQL actually executes the DELETE and removes the rows to measure real execution timing!', 'ANALYZE runs in read-only dry-run mode', 'Postgres refuses to explain DELETE', 'Only 1 row is tested']], ['question' => 'Which tiny index type is purpose-built for multi-billion-row append-only time-series tables physically ordered on disk?', 'answer' => 'BRIN (Block Range Index)', 'options' => ['BRIN (Block Range Index)', 'Hash Index', 'Full-Text GIN', 'SP-GiST']]],
        'Run `EXPLAIN SELECT ...` in the playground to inspect the query plan.'
    ),
    pg_ch('3. Indexing, Query Plans, Security & AI Scale', 'Row-Level Security (RLS), FOR UPDATE SKIP LOCKED, Partitioning, VACUUM & pgvector AI', 'postgres row level security rls, select for update skip locked, pgvector cosine distance, autovacuum tuning',
        'PostgreSQL powers modern AI and multi-tenant SaaS backends with kernel-enforced **Row-Level Security (RLS)**, lock-free job queues (**`FOR UPDATE SKIP LOCKED`**), declarative **Table Partitioning**, and **`pgvector` HNSW semantic search**.',
        ['**Row-Level Security (`ENABLE ROW LEVEL SECURITY`)**: Enforces `USING (tenant_id = current_setting(\'app.tenant_id\')::uuid)` directly inside Postgres so even a buggy query missing `WHERE tenant_id = ?` can **never** read another tenant\'s rows! (**Gotcha**: Table owners & superusers bypass RLS unless `FORCE ROW LEVEL SECURITY` is also set!)', '**`FOR UPDATE SKIP LOCKED`**: Turns any Postgres table into a rock-solid 10,000-jobs/sec concurrent queue where 20 workers grab distinct pending rows with zero lock contention!', '**`pgvector` (`<=>` Cosine Distance)**: Store `embedding vector(1536)` + `USING hnsw (embedding vector_cosine_ops)` to run hybrid SQL + AI RAG vector search inside one ACID transaction!'],
        [['`ENABLE` + `FORCE ROW LEVEL SECURITY`', 'Enforces tenant isolation policies even on table owner', 'Remember `BYPASSRLS` role attribute still bypasses RLS—connect apps with a non-superuser role!'], ['`FOR UPDATE SKIP LOCKED`', 'Locks available rows and skips rows locked by sibling workers', 'Industry-standard pattern behind SolidQueue, GoodJob, and transactional outboxes!'], ['`embedding <=> $1` (`pgvector`)', 'Cosine distance (`1 - cosine_similarity`) with HNSW index', '`<->` = L2 Euclidean, `<#>` = negative inner product, `<=>` = cosine distance.']],
